{"code":"import pandas as pd
import numpy as np
from decimal import Decimal, ROUND_HALF_UP

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

def clean_val(v):
    if pd.isna(v): return np.nan
    try: iv = int(v)
    except: return np.nan
    if iv < 0 or iv > 3: return np.nan
    return iv

def round_half_up(val):
    return int(Decimal(str(val)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

# RSES
# Negatively worded statements: 3, 5, 8, 9, 10
rses_neg = {3, 5, 8, 9, 10}

rses_totals = []
rses_prorated = []

for idx, row in raw.iterrows():
    item_scores = []
    valid_count = 0
    for i in range(1, 11):
        v = clean_val(row[f'rses_{i}'])
        if pd.isna(v):
            item_scores.append(np.nan)
        else:
            if i in rses_neg:
                item_scores.append(3 - v)
            else:
                item_scores.append(v)
            valid_count += 1

    n_missing = 10 - valid_count
    valid_scores = [s for s in item_scores if not pd.isna(s)]

    if n_missing >= 2:
        rses_totals.append(np.nan)
        rses_prorated.append(np.nan)
    elif n_missing == 1:
        s = sum(valid_scores)
        scaled = (s * 10) / 9.0
        rounded = round_half_up(scaled)
        rses_totals.append(float(rounded))
        rses_prorated.append(True)
    else:
        s = sum(valid_scores)
        rses_totals.append(float(s))
        rses_prorated.append(False)

my_rses = pd.DataFrame({
    'rses_total': rses_totals,
    'rses_prorated': rses_prorated
})

for col in my_rses.columns:
    eq = my_rses[col].eq(pipe[col]) | (my_rses[col].isna() & pipe[col].isna())
    mismatches = (~eq).sum()
    print(f"RSES col {col}: {mismatches} mismatches")
    if mismatches > 0:
        diff_df = pd.DataFrame({'my': my_rses[col], 'pipe': pipe[col], 'id': raw['respondent_id']})[~eq]
        print(diff_df.head(10))
